import test from 'node:test'
import assert from 'node:assert/strict'
import { installation, evidence } from './harness.mjs'

const today = new Date().toISOString().slice(0, 10)

test('TRACE-004 approved inspection plans hold failed work and lots from start, output, pick and ship until an authorized release after a passing retest', async t => {
  const h = await installation(); t.after(() => h.close())
  const manager = await h.person('quality-lead@example.test', 'manager'), operator = await h.person('line-operator@example.test', 'production')
  const warehouse = await h.person('dock@example.test', 'warehouse'), agent = await h.person('quality-agent@example.test', 'agent')
  const shop = await h.command('location.save', { name: 'Fill line' })
  const bar = await h.command('item.save', { sku: 'BAR-6061', name: 'Aluminium bar', kind: 'buy', baseUnit: 'each' })
  const bracket = await h.command('item.save', { sku: 'BRK-10', name: 'Bored bracket', kind: 'make', baseUnit: 'each' })
  const wax = await h.command('item.save', { sku: 'WAX-BASE', name: 'Balm base', kind: 'buy', baseUnit: 'each' })
  const tin = await h.command('item.save', { sku: 'BALM-4OZ', name: 'Balm tin 4 oz', kind: 'make', baseUnit: 'each' })
  await h.command('bom.revise', { itemId: bracket.id, components: [{ itemId: bar.id, quantity: '1' }], routing: [{ name: 'Bore', workCentre: 'Mill', minutes: 3 }, { name: 'Deburr', workCentre: 'Bench', minutes: 1 }] })
  await h.command('bom.revise', { itemId: tin.id, components: [{ itemId: wax.id, quantity: '1' }], routing: [{ name: 'Fill', workCentre: 'Filler', minutes: 1 }, { name: 'Lid', workCentre: 'Capper', minutes: 1 }] })
  await h.command('opening.record', { locationId: shop.id, countedOn: today, valuationBasis: 'supplier-invoice', countedBy: 'Olive', evidence: evidence(), lines: [{ itemId: bar.id, quantity: '20', unitCost: '4' }, { itemId: wax.id, quantity: '60', unitCost: '1' }] })
  const customer = await h.command('party.save', { name: 'Harbor Hardware', kind: 'customer' })

  // A qualified person approves a plan someone else prepared; agents and self-approval are refused.
  const bore = { itemId: bracket.id, revision: 1, stage: 'in-process', operationSequence: 1, name: 'Bore check', sampleSize: 5, measurements: [{ name: 'Bore diameter', unit: 'mm', target: '10', lower: '9.98', upper: '10.02' }], attachments: [evidence('Drawing BRK-10 rev A: bore 10.00 ±0.02 mm')] }
  await agent.run('quality.plan.save', bore, { error: 'FORBIDDEN' })
  await operator.run('quality.plan.save', { ...bore, measurements: [{ name: 'Bore diameter', unit: 'mm', target: '10.05', lower: '9.98', upper: '10.02' }] }, { error: 'INPUT' })
  await operator.run('quality.plan.save', { ...bore, revision: 7 }, { error: 'INPUT' })
  let borePlan = await operator.run('quality.plan.save', bore)
  assert.equal(borePlan.status, 'draft'); assert.equal(borePlan.attachments.length, 1)
  await operator.run('quality.plan.approve', { planId: borePlan.id, version: borePlan.version }, { error: 'FORBIDDEN' })
  await agent.run('quality.plan.approve', { planId: borePlan.id, version: borePlan.version }, { error: 'FORBIDDEN' })
  const draftOnly = await h.command('wo.draft', { itemId: bracket.id, quantity: '6', requiredBy: today, reason: 'Bracket batch' })
  let work = await h.command('wo.release', { workOrderId: draftOnly.id, version: draftOnly.version })
  const samples = values => ({ 'Bore diameter': values })
  await operator.run('quality.inspect', { planId: borePlan.id, planVersion: borePlan.version, workOrderId: work.id, samples: samples(['10', '10', '10', '10', '10']) }, { error: 'STATE' })
  borePlan = await manager.run('quality.plan.approve', { planId: borePlan.id, version: borePlan.version })
  assert.equal(borePlan.approval.by, manager.id)

  // Operation 1 runs; output needs a batch lot because required checks hold stock by lot.
  const op = async (who, type, sequence, more = {}) => { work = await who.run(type, { workOrderId: work.id, version: work.version, sequence, ...more }); return work }
  await op(manager, 'wo.operation.assign', 1, { operatorId: operator.id }); await op(manager, 'wo.operation.assign', 2, { operatorId: operator.id })
  await operator.run('quality.inspect', { planId: borePlan.id, planVersion: borePlan.version, workOrderId: work.id, samples: samples(['10', '10', '10', '10', '10']) }, { error: 'STATE' })
  await op(operator, 'wo.operation.start', 1, { workCentre: 'Mill', station: 'Mill 1', reason: 'Bore the batch' })
  await operator.run('wo.output', { workOrderId: work.id, version: work.version, locationId: shop.id, quantity: '4' }, { error: 'INPUT' })
  work = await operator.run('wo.output', { workOrderId: work.id, version: work.version, locationId: shop.id, quantity: '4', lot: 'BRK-A' })
  let s = await h.state()
  const lotA = s.lots.find(l => l.code === 'BRK-A')

  // Pick and pack the batch before its check fails.
  const quote = await h.command('so.quote', { customerId: customer.id, promiseDate: today, lines: [{ itemId: bracket.id, quantity: '4', unitPrice: '30' }] })
  const order = await h.command('so.confirm', { orderId: quote.id, version: quote.version }); await h.command('so.reserve', { orderId: order.id })
  let shipment = await warehouse.run('shipment.pick', { orderId: order.id, lines: [{ lineId: order.lines[0].id, locationId: shop.id, quantity: '4', lotId: lotA.id }] })
  shipment = await warehouse.run('shipment.pack', { shipmentId: shipment.id, version: shipment.version, packages: 1 })

  // Fail the dimensional check with attached measurements: the lot, operations and shipment are held.
  await agent.run('quality.inspect', { planId: borePlan.id, planVersion: borePlan.version, workOrderId: work.id, samples: samples(['10', '10', '10', '10', '10']) }, { error: 'FORBIDDEN' })
  await operator.run('quality.inspect', { planId: borePlan.id, planVersion: borePlan.version, workOrderId: work.id, samples: samples(['10', '10.01', '10']) }, { error: 'SAMPLE_SIZE' })
  const failed = await operator.run('quality.inspect', { planId: borePlan.id, planVersion: borePlan.version, workOrderId: work.id, samples: samples(['10.00', '10.01', '10.03', '9.99', '10.00']), evidence: [evidence('CMM report: bore 10.03 mm on part 3')] })
  assert.equal(failed.passed, false)
  assert.deepEqual(failed.measurements.map(m => [m.count, m.mean, m.outside, m.passed, m.samples]), [[5, '10.006', 1, false, ['10', '10.01', '10.03', '9.99', '10']]])
  assert.equal(failed.evidence[0].name, 'count-sheet.txt'); assert.ok(failed.holdId)
  s = await h.invariant()
  const hold = s.qualityHolds.find(x => x.id === failed.holdId)
  assert.equal(hold.status, 'open'); assert.deepEqual(hold.held, [{ lotId: lotA.id, locationId: shop.id, quantity: '4' }])
  assert.deepEqual(hold.unreserved.map(r => [r.demandId, r.quantity]), [[order.id, '4']])
  assert.deepEqual(s.positions.filter(p => p.lotId === lotA.id).map(p => [p.status, p.quantity]), [['quarantine', '4']])
  assert.equal(s.lots.find(l => l.id === lotA.id).status, 'quality hold')
  await op(operator, 'wo.operation.complete', 1, { reason: 'Bored' })
  const gate = s.dispatch.find(d => d.workOrderId === work.id && d.sequence === 2).gates.find(g => g.code === 'QUALITY_HOLD')
  assert.match(gate.message, /^Quality hold: Bore check failed on .*Bore diameter 1 of 5 outside 9\.98–10\.02 mm, mean 10\.006/)
  s = await operator.run('wo.operation.start', { workOrderId: work.id, version: work.version, sequence: 2, workCentre: 'Bench', station: 'Bench 1', reason: 'Deburr' }, { error: 'QUALITY_HOLD' })
  assert.equal(s.error.message, gate.message)
  assert.equal((await h.state(operator.cookie)).dispatch.find(d => d.workOrderId === work.id && d.sequence === 2).gates[0].message, gate.message)
  await operator.run('wo.output', { workOrderId: work.id, version: work.version, locationId: shop.id, quantity: '1', lot: 'BRK-B' }, { error: 'QUALITY_HOLD' })
  await warehouse.run('shipment.ship', { shipmentId: shipment.id, version: shipment.version, carrier: 'UPS' }, { error: 'QUALITY_HOLD' })
  await warehouse.run('shipment.pick', { orderId: order.id, lines: [{ lineId: order.lines[0].id, locationId: shop.id, quantity: '1', lotId: lotA.id }] }, { error: 'NOT_RESERVED' })
  await warehouse.run('quarantine.decide', { itemId: bracket.id, locationId: shop.id, lotId: lotA.id, quantity: '4', decision: 'release', reason: 'Looks fine' }, { error: 'QUALITY_HOLD' })

  // Release needs a later passing retest, a qualified person other than the failing inspector, and evidence.
  await manager.run('quality.release', { holdId: hold.id, version: hold.version, reason: 'Reworked', evidence: [evidence('Rework note')] }, { error: 'RETEST' })
  const retest = await operator.run('quality.inspect', { planId: borePlan.id, planVersion: borePlan.version, workOrderId: work.id, samples: samples(['10.00', '10.01', '10.02', '9.99', '10.00']), evidence: [evidence('CMM retest after rework')] })
  assert.equal(retest.passed, true); assert.equal(retest.retestOf, failed.id); assert.equal(retest.holdId, undefined)
  await operator.run('quality.release', { holdId: hold.id, version: hold.version, reason: 'Retest passed', evidence: [evidence('Retest')] }, { error: 'FORBIDDEN' })
  await agent.run('quality.release', { holdId: hold.id, version: hold.version, reason: 'Retest passed', evidence: [evidence('Retest')] }, { error: 'FORBIDDEN' })
  await manager.run('quality.release', { holdId: hold.id, version: hold.version, reason: 'Retest passed' }, { error: 'EVIDENCE' })
  const released = await manager.run('quality.release', { holdId: hold.id, version: hold.version, reason: 'Retest passed after rework', evidence: [evidence('Signed retest record')] })
  assert.equal(released.status, 'released'); assert.equal(released.release.retestId, retest.id); assert.deepEqual(released.release.released, [{ lotId: lotA.id, locationId: shop.id, quantity: '4' }])
  s = await h.invariant()
  assert.deepEqual(s.positions.filter(p => p.lotId === lotA.id).map(p => [p.status, p.quantity]), [['available', '4']])
  assert.equal(s.lots.find(l => l.id === lotA.id).status, 'released')
  assert.deepEqual(s.inspections.filter(x => x.subjectId === work.id).map(x => [x.id, x.passed]), [[failed.id, false], [retest.id, true]])
  assert.equal(s.dispatch.find(d => d.workOrderId === work.id && d.sequence === 2).gates.some(g => g.code === 'QUALITY_HOLD'), false)
  await op(operator, 'wo.operation.start', 2, { workCentre: 'Bench', station: 'Bench 1', reason: 'Deburr' })
  await h.command('so.reserve', { orderId: order.id })
  assert.equal((await warehouse.run('shipment.ship', { shipmentId: shipment.id, version: shipment.version, carrier: 'UPS' })).status, 'shipped')

  // Fill weight during production: count, exact mean and pass/fail against the approved rule on each batch.
  const fillRule = { itemId: tin.id, revision: null, stage: 'in-process', operationSequence: 1, name: 'Fill weight', sampleSize: 20, measurements: [{ name: 'Fill weight', unit: 'oz', target: '4.0', lower: '3.95', upper: '4.15' }] }
  let fill = await manager.run('quality.plan.save', fillRule)
  fill = await h.command('quality.plan.approve', { planId: fill.id, version: fill.version })
  const batch = async (lot, weights) => {
    const draft = await h.command('wo.draft', { itemId: tin.id, quantity: '20', requiredBy: today, reason: `Batch ${lot}` })
    let w = await h.command('wo.release', { workOrderId: draft.id, version: draft.version })
    w = await manager.run('wo.operation.assign', { workOrderId: w.id, version: w.version, sequence: 1, operatorId: operator.id })
    w = await operator.run('wo.operation.start', { workOrderId: w.id, version: w.version, sequence: 1, workCentre: 'Filler', station: 'Filler 1', reason: 'Fill tins' })
    w = await operator.run('wo.output', { workOrderId: w.id, version: w.version, locationId: shop.id, quantity: '20', lot })
    return { w, result: await operator.run('quality.inspect', { planId: fill.id, planVersion: fill.version, workOrderId: w.id, samples: { 'Fill weight': weights } }) }
  }
  const pass = await batch('BB-1020', [...Array(10).fill('4.02'), ...Array(10).fill('4.04')])
  assert.deepEqual(pass.result.measurements.map(m => [m.count, m.mean, m.lower, m.upper, m.unit, m.passed]), [[20, '4.03', '3.95', '4.15', 'oz', true]])
  assert.equal(pass.result.holdId, undefined)
  const fail = await batch('BB-1021', [...Array(18).fill('4.01'), '3.9', '3.92'])
  assert.deepEqual(fail.result.measurements.map(m => [m.count, m.mean, m.outside, m.passed]), [[20, '4', 2, false]])
  s = await h.invariant()
  const lot = code => s.lots.find(l => l.code === code)
  assert.deepEqual([lot('BB-1020').status, lot('BB-1021').status], ['released', 'quality hold'])
  assert.deepEqual(s.positions.filter(p => [lot('BB-1020').id, lot('BB-1021').id].includes(p.lotId)).map(p => [p.lotId === lot('BB-1020').id ? 'BB-1020' : 'BB-1021', p.status, p.quantity]).sort(), [['BB-1020', 'available', '20'], ['BB-1021', 'quarantine', '20']])
  assert.equal(s.inspections.find(x => x.id === pass.result.id).planVersion, fill.version)

  // A newer approved plan supersedes the old one; results keep the version they were scored under.
  let tighter = await manager.run('quality.plan.save', { ...fillRule, sampleSize: 10 })
  tighter = await h.command('quality.plan.approve', { planId: tighter.id, version: tighter.version })
  s = await h.state()
  assert.equal(s.inspectionPlans.find(p => p.id === fill.id).status, 'superseded')
  await operator.run('quality.inspect', { planId: fill.id, planVersion: s.inspectionPlans.find(p => p.id === fill.id).version, workOrderId: fail.w.id, samples: { 'Fill weight': Array(20).fill('4') } }, { error: 'STATE' })

  // Receipt inspection plans apply to received supplier lots.
  const supplier = await h.command('party.save', { name: 'Wax Works', kind: 'supplier' })
  let po = await h.command('po.draft', { supplierId: supplier.id, expectedDate: today, reason: 'Balm base', lines: [{ itemId: wax.id, quantity: '10', unitPrice: '1' }] })
  po = await h.command('po.approve', { poId: po.id, version: po.version })
  const receipt = await warehouse.run('receipt.create', { poId: po.id, supplierReference: 'WW-9', lines: [{ lineId: po.lines[0].id, locationId: shop.id, quantity: '10', lot: 'WAX-77' }] })
  let melt = await operator.run('quality.plan.save', { itemId: wax.id, stage: 'receipt', name: 'Melt point', sampleSize: 3, measurements: [{ name: 'Melt point', unit: '°C', target: '62', lower: '60', upper: '64' }] })
  melt = await manager.run('quality.plan.approve', { planId: melt.id, version: melt.version })
  const meltFail = await operator.run('quality.inspect', { planId: melt.id, planVersion: melt.version, lotId: receipt.lines[0].lotId, samples: { 'Melt point': ['59.5', '62', '61'] } })
  s = await h.invariant()
  assert.equal(s.qualityHolds.find(x => x.id === meltFail.holdId).subjectKind, 'lots')
  assert.deepEqual(s.positions.filter(p => p.lotId === receipt.lines[0].lotId).map(p => [p.status, p.quantity]), [['quarantine', '10']])
  // A held lot may still leave through quarantine rejection without a retest; release stays refused.
  await warehouse.run('quarantine.decide', { itemId: wax.id, locationId: shop.id, lotId: receipt.lines[0].lotId, quantity: '10', decision: 'release', reason: 'Use it' }, { error: 'QUALITY_HOLD' })
  await warehouse.run('quarantine.decide', { itemId: wax.id, locationId: shop.id, lotId: receipt.lines[0].lotId, quantity: '10', decision: 'reject', reason: 'Returned to Wax Works: melt point low' })
  s = await h.invariant()
  assert.deepEqual(s.positions.filter(p => p.lotId === receipt.lines[0].lotId), [])
  assert.equal(s.lots.find(l => l.id === receipt.lines[0].lotId).status, 'rejected')
})

test('TRACE-005 quantity-scoped cases retain complaints, CAPA, supplier/rework routing, passing-only independent release and evidenced effectiveness across restart and restore', async t => {
  const h = await installation(); t.after(() => h.close())
  const manager = await h.person('case-manager@example.test', 'manager'), inspector = await h.person('case-inspector@example.test', 'production')
  const warehouse = await h.person('case-dock@example.test', 'warehouse'), agent = await h.person('case-agent@example.test', 'agent')
  const reviewer = await h.person('case-reviewer@example.test', 'manager')
  const location = await h.command('location.save', { name: 'NC shelf' })
  const item = await h.command('item.save', { sku: 'NC-PLATE', name: 'Plate', kind: 'make', baseUnit: 'each' })
  const component = await h.command('item.save', { sku: 'NC-RAW', name: 'Plate blank', kind: 'buy', baseUnit: 'each' })
  const supplier = await h.command('party.save', { name: 'Plate supplier', kind: 'supplier' })
  await h.command('opening.record', { locationId: location.id, countedOn: today, valuationBasis: 'supplier-invoice', countedBy: 'Owner', evidence: evidence(), lines: [{ itemId: component.id, quantity: '10', unitCost: '2', lot: 'NC-RAW' }] })
  await h.command('bom.revise', { itemId: item.id, components: [{ itemId: component.id, quantity: '1' }] })
  let work = await h.command('wo.draft', { itemId: item.id, quantity: '10', requiredBy: today, reason: 'NC batch' })
  work = await h.command('wo.release', { workOrderId: work.id, version: work.version })
  await h.command('wo.issue', { workOrderId: work.id, lines: [{ itemId: component.id, locationId: location.id, quantity: '10' }] })
  work = (await h.state()).workOrders.find(w => w.id === work.id)
  await h.command('wo.output', { workOrderId: work.id, version: work.version, locationId: location.id, quantity: '10', lot: 'NC-FINISHED' })
  const lot = (await h.state()).lots.find(l => l.code === 'NC-FINISHED')
  const customer = await h.command('party.save', { name: 'Case customer', kind: 'customer' })
  let demand = await h.command('so.quote', { customerId: customer.id, promiseDate: today, lines: [{ itemId: item.id, quantity: '8', unitPrice: '8' }] })
  demand = await h.command('so.confirm', { orderId: demand.id, version: demand.version })
  await h.command('so.reserve', { orderId: demand.id })
  const input = { lotId: lot.id, locationId: location.id, quantity: '4', complaint: 'Customer reports rough edges on four plates', dueOn: today, evidence: [evidence('Complaint photographs')] }
  await agent.run('nonconformance.open', input, { error: 'FORBIDDEN' })
  await warehouse.run('nonconformance.open', input, { error: 'FORBIDDEN' })
  await manager.run('nonconformance.open', { ...input, quantity: '11' }, { error: 'INSUFFICIENT_STOCK' })
  const commandId = crypto.randomUUID()
  let n = await manager.run('nonconformance.open', input, { commandId })
  assert.deepEqual(await manager.run('nonconformance.open', input, { commandId }), n)
  assert.equal(n.ownerId, manager.id); assert.equal(n.quantity, '4'); assert.equal(n.dueOn, today); assert.equal(n.unitCost, '2')
  assert.deepEqual(n.unreserved.map(r => [r.demandId, r.quantity]), [[demand.id, '2']])
  assert.equal(n.evidence[0].sha256.length, 64)
  let s = await h.invariant()
  assert.equal(s.nonconformances.length, 1)
  assert.deepEqual(s.positions.filter(p => p.lotId === lot.id).map(p => [p.status, p.quantity]).sort(), [['available', '6'], ['quarantine', '4']])
  await warehouse.run('quarantine.decide', { itemId: item.id, locationId: location.id, lotId: lot.id, quantity: '1', decision: 'release', reason: 'Bypass' }, { error: 'NONCONFORMANCE' })
  await warehouse.run('quarantine.decide', { itemId: item.id, locationId: location.id, lotId: lot.id, quantity: '1', decision: 'reject', reason: 'Bypass' }, { error: 'NONCONFORMANCE' })
  await h.command('movement.reverse', { documentKind: 'workOrders', documentId: work.id, reason: 'Bypass source' }, { error: 'DEPENDENCY' })
  const repair = await h.command('rework.draft', { kind: 'rework', sourceLotId: lot.id, sourceJobId: work.id, locationId: location.id, sourceStatus: 'quarantine', quantity: '2', disposition: 'Polish edges', instructions: 'Polish and inspect all four', evidence: [evidence('Repair instructions')], outputs: [{ itemId: item.id, quantity: '2', lot: 'NC-REPAIR', value: '4' }] })
  n = await manager.run('nonconformance.update', { caseId: n.id, version: n.version, rootCause: 'Worn polishing belt', correctiveAction: 'Replace belt; inspect first-off output', nextAction: 'Supplier reviews blank edge finish; repair order prepared in app', supplierId: supplier.id, reworkOrderId: repair.id, dueOn: today, evidence: [evidence('Supplier action and repair routing')] })
  assert.equal(n.actions[0].supplierId, supplier.id); assert.equal(n.actions[0].reworkOrderId, repair.id); assert.equal(n.actions[0].delivery, 'recorded in app')
  await manager.run('nonconformance.update', { caseId: n.id, version: n.version - 1 }, { error: 'STALE' })
  const release = { caseId: n.id, version: n.version, quantity: '2', reason: 'Two plates passed', evidence: [evidence('Signed disposition')] }
  await manager.run('nonconformance.release', release, { error: 'FORBIDDEN' })
  await agent.run('nonconformance.release', release, { error: 'FORBIDDEN' })
  await h.command('nonconformance.close', { caseId: n.id, version: n.version, effective: true, check: 'Not yet' }, { error: 'QUANTITY' })
  let plan = await h.command('quality.plan.save', { itemId: item.id, stage: 'final', name: 'Edge finish', sampleSize: 2, measurements: [{ name: 'Roughness', unit: 'um', target: '1', lower: '0', upper: '2' }] })
  plan = await h.command('quality.plan.approve', { planId: plan.id, version: plan.version })
  const inspect = values => inspector.run('quality.inspect', { planId: plan.id, planVersion: plan.version, nonconformanceId: n.id, quantity: '2', samples: { Roughness: values }, evidence: [evidence('Measured two passing units')] })
  const failResult = await inspect(['1', '3'])
  await h.command('nonconformance.release', { ...release, inspectionId: failResult.id }, { error: 'RETEST' })
  await reviewer.run('quality.inspect', { planId: plan.id, planVersion: plan.version, nonconformanceId: n.id, quantity: '2', samples: { Roughness: ['1', '3'] } })
  const passed = await inspect(['1', '2'])
  await reviewer.run('nonconformance.release', { ...release, inspectionId: passed.id }, { error: 'FORBIDDEN' })
  await h.command('nonconformance.release', { ...release, quantity: '3', inspectionId: passed.id }, { error: 'RETEST' })
  const id = crypto.randomUUID()
  n = await h.command('nonconformance.release', { ...release, inspectionId: passed.id }, { commandId: id })
  assert.equal(n.remaining, '2'); assert.equal(n.decisions[0].inspectionId, passed.id)
  assert.deepEqual(await h.command('nonconformance.release', { ...release, inspectionId: passed.id }, { commandId: id }), n)
  await h.command('nonconformance.release', { ...release, version: n.version, inspectionId: passed.id }, { error: 'RETEST' })
  s = await h.invariant()
  assert.deepEqual(s.positions.filter(p => p.lotId === lot.id).map(p => [p.status, p.quantity]).sort(), [['available', '8'], ['quarantine', '2']])
  let routed = (await h.state()).reworkOrders.find(w => w.id === repair.id)
  assert.equal(routed.nonconformanceId, n.id)
  routed = await h.command('rework.approve', { orderId: routed.id, version: routed.version, reason: 'Independent repair approval' })
  routed = await h.command('rework.execute', { orderId: routed.id, version: routed.version })
  n = (await h.state()).nonconformances.find(x => x.id === n.id)
  assert.equal(n.remaining, '0'); assert.equal(n.decisions.at(-1).orderId, repair.id)
  await h.command('nonconformance.close', { caseId: n.id, version: n.version, effective: true, check: 'Repair not released', evidence: [evidence()] }, { error: 'REWORK_RELEASE' })
  await h.command('rework.release', { orderId: routed.id, version: routed.version, reason: 'Try before inspection', evidence: [evidence()] }, { error: 'RETEST' })
  await inspector.run('quality.inspect', { planId: plan.id, planVersion: plan.version, reworkOrderId: routed.id, samples: { Roughness: ['1', '1'] }, evidence: [evidence('Repair inspection')] })
  routed = await h.command('rework.release', { orderId: routed.id, version: routed.version, reason: 'Repair passed inspection', evidence: [evidence('Signed repair release')] })
  assert.equal(routed.status, 'released')
  await h.command('nonconformance.close', { caseId: n.id, version: n.version, effective: false, check: 'Not effective', evidence: [evidence()] }, { error: 'EFFECTIVENESS' })
  await h.command('nonconformance.close', { caseId: n.id, version: n.version, effective: true, check: 'Next batch has no recurrence' }, { error: 'INPUT' })
  n = await h.command('nonconformance.close', { caseId: n.id, version: n.version, effective: true, check: 'Next batch inspected; belt replacement effective', evidence: [evidence('Next-batch inspection report')] })
  assert.equal(n.status, 'closed'); assert.equal(n.effectiveness.effective, true)
  const trace = await (await h.request(`/api/larder/lots/${lot.id}/trace`)).json()
  assert.ok(trace.rows.some(r => r.kind === 'nonconformance' && r.reference === n.reference))
  await h.restart()
  assert.deepEqual((await h.state()).nonconformances.find(x => x.id === n.id), n)
  let returned = await h.command('nonconformance.open', { ...input, quantity: '1' })
  returned = await h.command('nonconformance.return', { caseId: returned.id, version: returned.version, quantity: '1', supplierId: supplier.id, supplierReference: 'MANUAL-RETURN-1', reason: 'Supplier accepted return instructions', evidence: [evidence('Recorded physical supplier return')] })
  assert.equal(returned.remaining, '0'); assert.equal(returned.decisions[0].delivery, 'recorded in app; not provider-confirmed')
  assert.equal(returned.decisions[0].supplierReference, 'MANUAL-RETURN-1')
  const archive = await (await h.request('/api/larder/archive')).json()
  const target = await installation(); t.after(() => target.close())
  const restored = await target.request('/api/larder/archive/restore', { method: 'POST', body: archive })
  assert.equal(restored.status, 200, await restored.text())
  assert.deepEqual((await target.invariant()).nonconformances, [n, returned])
  assert.equal((await target.state()).reworkOrders.find(w => w.id === routed.id).status, 'released')
  for (const file of [n.evidence[0], n.actions[0].evidence[0], n.effectiveness.evidence[0]]) {
    const res = await target.request(`/api/larder/attachments/${file.id}`); assert.equal(res.status, 200)
    assert.equal((await res.arrayBuffer()).byteLength, file.size)
  }
})

test('TRACE-006 immediate recall containment expands exact genealogy, identifies two customers, protects stock/WIP and exports durable honest evidence', async t => {
  const h = await installation(); t.after(() => h.close())
  const manager = await h.person('recall-manager@example.test', 'manager')
  const warehouse = await h.person('recall-dock@example.test', 'warehouse')
  const agent = await h.person('recall-agent@example.test', 'agent')
  const location = await h.command('location.save', { name: 'Recall shelf' })
  const safeLocation = await h.command('location.save', { name: 'Unaffected shelf' })
  const raw = await h.command('item.save', { sku: 'RECALL-ING', name: 'Ingredient', kind: 'buy', baseUnit: 'kg' })
  const product = await h.command('item.save', { sku: 'RECALL-TIN', name: 'Finished tin', kind: 'make', baseUnit: 'each' })
  const supplier = await h.command('party.save', { name: 'Ingredient supplier', kind: 'supplier' })
  await h.command('bom.revise', { itemId: product.id, components: [{ itemId: raw.id, quantity: '1' }], routing: [{ name: 'Fill', workCentre: 'Filler', minutes: 1 }] })
  let po = await h.command('po.draft', { supplierId: supplier.id, expectedDate: today, reason: 'Recall trace', lines: [{ itemId: raw.id, quantity: '16', unitPrice: '2' }] })
  po = await h.command('po.approve', { poId: po.id, version: po.version })
  const receive = async (lot, quantity) => (await h.command('receipt.create', { poId: po.id, supplierReference: lot, lines: [{ lineId: po.lines[0].id, locationId: location.id, quantity, lot }] })).lines[0].lotId
  const bad = await receive('ING-BAD', '12'), clean = await receive('ING-CLEAN', '4')
  const batch = async (lotId, quantity, code) => {
    let w = await h.command('wo.draft', { itemId: product.id, quantity, requiredBy: today, reason: code })
    w = await h.command('wo.release', { workOrderId: w.id, version: w.version })
    w = await h.command('wo.issue', { workOrderId: w.id, lines: [{ itemId: raw.id, locationId: location.id, lotId, quantity }] })
    if (code !== 'WIP') w = await h.command('wo.output', { workOrderId: w.id, version: w.version, locationId: code === 'RECALL-SAFE' ? safeLocation.id : location.id, quantity, lot: code })
    return w
  }
  const a = await batch(bad, '4', 'RECALL-A'), b = await batch(bad, '4', 'RECALL-B')
  const safeWork = await batch(clean, '2', 'RECALL-SAFE'), wip = await batch(bad, '2', 'WIP')
  const s0 = await h.state(), lot = code => s0.lots.find(l => l.code === code)
  const ship = async (customerName, lotId, quantity, locationId = location.id) => {
    const customer = await h.command('party.save', { name: customerName, kind: 'customer' })
    let order = await h.command('so.quote', { customerId: customer.id, promiseDate: today, lines: [{ itemId: product.id, quantity, unitPrice: '10' }] })
    order = await h.command('so.confirm', { orderId: order.id, version: order.version })
    let sh = await h.command('shipment.pick', { orderId: order.id, lines: [{ lineId: order.lines[0].id, locationId, lotId, quantity }] })
    sh = await h.command('shipment.pack', { shipmentId: sh.id, version: sh.version, packages: 1 })
    return { customer, order, shipment: await h.command('shipment.ship', { shipmentId: sh.id, version: sh.version, carrier: 'Collection' }) }
  }
  const first = await ship('Recall buyer A', lot('RECALL-A').id, '2'), second = await ship('Recall buyer B', lot('RECALL-B').id, '1')
  // A prepared shipment must not escape a hold placed after packing.
  let pending = await h.command('so.quote', { customerId: second.customer.id, promiseDate: today, lines: [{ itemId: product.id, quantity: '1', unitPrice: '10' }] })
  pending = await h.command('so.confirm', { orderId: pending.id, version: pending.version })
  let packed = await h.command('shipment.pick', { orderId: pending.id, lines: [{ lineId: pending.lines[0].id, locationId: location.id, lotId: lot('RECALL-B').id, quantity: '1' }] })
  packed = await h.command('shipment.pack', { shipmentId: packed.id, version: packed.version, packages: 1 })
  const input = { lotId: bad, reason: 'Supplier reports contaminated ingredient', evidence: [evidence('Supplier batch warning')] }
  await manager.run('recall.open', { ...input, evidence: [] }, { error: 'INPUT' })
  assert.deepEqual((await h.state()).recalls, [])
  await agent.run('recall.open', input, { error: 'FORBIDDEN' })
  await warehouse.run('recall.open', input, { error: 'FORBIDDEN' })
  const before = await h.invariant(), id = crypto.randomUUID()
  let r = await manager.run('recall.open', input, { commandId: id })
  assert.deepEqual(await manager.run('recall.open', input, { commandId: id }), r)
  assert.equal(r.ownerId, manager.id); assert.equal(r.ownerName, 'recall-manager')
  assert.deepEqual([...r.lotIds].sort(), [bad, lot('RECALL-A').id, lot('RECALL-B').id].sort())
  assert.ok(r.workOrderIds.includes(wip.id)); assert.ok(!r.workOrderIds.includes(safeWork.id))
  assert.deepEqual(r.held.map(x => x.quantity).sort(), ['2', '2', '3'])
  assert.ok(r.unreserved.some(x => x.demandId === pending.id && x.quantity === '1'))
  let s = await h.invariant()
  assert.deepEqual(s.movements.slice(0, before.movements.length), before.movements)
  assert.equal(s.positions.filter(p => r.lotIds.includes(p.lotId) && p.status === 'available').length, 0)
  assert.equal(s.positions.find(p => p.lotId === lot('RECALL-SAFE').id).quantity, '2')
  const gate = s.dispatch.find(d => d.workOrderId === wip.id).gates.find(g => g.code === 'RECALL_HOLD')
  assert.match(gate.message, new RegExp(r.reference)); assert.match(gate.message, /owner recall-manager/)
  let current = s.workOrders.find(w => w.id === wip.id)
  current = await h.command('wo.operation.assign', { workOrderId: current.id, version: current.version, sequence: 1, operatorId: manager.id })
  const refused = await manager.run('wo.operation.start', { workOrderId: current.id, version: current.version, sequence: 1, workCentre: 'Filler', station: '1', reason: 'Try recalled WIP' }, { error: 'RECALL_HOLD' })
  assert.equal(refused.error.message, gate.message)
  await h.command('wo.output', { workOrderId: current.id, version: current.version, locationId: location.id, quantity: '2', lot: 'BYPASS-WIP' }, { error: 'RECALL_HOLD' })
  const split = await h.command('wo.split', { workOrderId: current.id, version: current.version, reason: 'Transfer recalled WIP retains its hold', parts: [{ quantity: '1' }, { quantity: '1' }] })
  for (const workOrderId of split.destinations) {
    const state = await h.state(), child = state.workOrders.find(w => w.id === workOrderId)
    assert.equal(state.dispatch.find(d => d.workOrderId === child.id).gates.find(g => g.code === 'RECALL_HOLD').message, gate.message)
    await h.command('wo.output', { workOrderId: child.id, version: child.version, locationId: location.id, quantity: '1', lot: 'BYPASS-SPLIT', allocations: [{ movementId: state.workMaterialPools[child.id][0].movementId, quantity: '1' }] }, { error: 'RECALL_HOLD' })
  }
  const splitState = await h.state()
  const merged = await h.command('wo.merge', { reason: 'Merge recalled WIP retains its hold', sources: split.destinations.map(id => ({ workOrderId: id, version: splitState.workOrders.find(w => w.id === id).version })) })
  const mergedState = await h.state(), mergedWork = mergedState.workOrders.find(w => w.id === merged.destinations[0])
  assert.equal(mergedState.dispatch.find(d => d.workOrderId === mergedWork.id).gates.find(g => g.code === 'RECALL_HOLD').message, gate.message)
  await h.command('wo.output', { workOrderId: mergedWork.id, version: mergedWork.version, locationId: location.id, quantity: '2', lot: 'BYPASS-MERGE' }, { error: 'RECALL_HOLD' })
  await warehouse.run('shipment.ship', { shipmentId: packed.id, version: packed.version, carrier: 'Bypass' }, { error: 'RECALL_HOLD' })
  await warehouse.run('quarantine.decide', { itemId: product.id, locationId: location.id, lotId: lot('RECALL-A').id, quantity: '1', decision: 'release', reason: 'Bypass' }, { error: 'RECALL_HOLD' })
  await warehouse.run('quarantine.decide', { itemId: product.id, locationId: location.id, lotId: lot('RECALL-A').id, quantity: '1', decision: 'reject', reason: 'Unrecorded recall disposal' }, { error: 'RECALL_HOLD' })
  // A source lot with zero available stock still cannot return via shipment reversal.
  await h.command('movement.reverse', { documentKind: 'shipments', documentId: first.shipment.id, reason: 'Bypass hold' }, { error: 'RECALL_HOLD' })
  let repair = await h.command('rework.draft', { kind: 'rework', sourceLotId: lot('RECALL-A').id, sourceJobId: a.id, locationId: location.id, sourceStatus: 'quarantine', quantity: '1', disposition: 'Bypass', instructions: 'Repair', evidence: [evidence()], outputs: [{ itemId: product.id, quantity: '1', value: '2', lot: 'BYPASS-REPAIR' }] })
  repair = await h.command('rework.approve', { orderId: repair.id, version: repair.version, reason: 'Try repair' })
  await h.command('rework.execute', { orderId: repair.id, version: repair.version }, { error: 'RECALL_HOLD' })
  await manager.run('recall.expand', { recallId: r.id, version: 0 }, { error: 'STALE' })
  r = await manager.run('recall.expand', { recallId: r.id, version: r.version })
  assert.equal(r.expansions.length, 2); assert.equal(r.held.length, 3)
  // Independent batches remain usable, even for the same SKU and location.
  await ship('Unaffected buyer', lot('RECALL-SAFE').id, '1', safeLocation.id)
  await warehouse.run('return.receive', { orderId: first.order.id, lineId: first.order.lines[0].id, quantity: '1', locationId: location.id, disposition: 'restock', reason: 'Recalled return must remain held' }, { error: 'RECALL_HOLD' })
  const returned = await warehouse.run('return.receive', { orderId: first.order.id, lineId: first.order.lines[0].id, quantity: '1', locationId: location.id, disposition: 'quarantine', reason: 'Physical recall return recorded' })
  const pack = await (await h.request(`/api/larder/recalls/${r.id}.json`)).json()
  assert.equal(pack.format, 'larder-recall-containment-v1'); assert.equal(pack.complete, false)
  assert.deepEqual(pack.shipments.map(x => x.customerId).sort(), [first.customer.id, second.customer.id].sort())
  assert.deepEqual(pack.shipments.map(x => x.lines[0].netShipped).sort(), ['1', '2'])
  assert.equal(pack.shipments.find(x => x.customerId === first.customer.id).lines[0].returns[0].returnId, returned.id)
  assert.equal(pack.shipments.find(x => x.customerId === first.customer.id).lines[0].returns[0].quantity, '1')
  assert.equal(pack.positions.every(p => p.unit && p.status === 'quarantine'), true)
  assert.match(pack.gaps.join(' '), /delivery.*not implemented/)
  assert.match(pack.gaps.join(' '), /reconciliation.*not implemented/)
  assert.equal((await h.request(`/api/larder/recalls/${r.id}.json`, { as: '' })).status, 401)
  await h.restart()
  assert.deepEqual((await h.state()).recalls, [r])
  const archive = await (await h.request('/api/larder/archive')).json()
  const target = await installation(); t.after(() => target.close())
  const restored = await target.request('/api/larder/archive/restore', { method: 'POST', body: archive })
  assert.equal(restored.status, 200, await restored.text())
  assert.deepEqual((await target.invariant()).recalls, [r])
  const retained = await (await target.request(`/api/larder/recalls/${r.id}.json`)).json()
  assert.deepEqual(retained.shipments, pack.shipments)
  const file = await target.request(`/api/larder/attachments/${r.evidence[0].id}`)
  assert.equal(await file.text(), 'Supplier batch warning')
  await h.command('role.set', { operatorId: manager.id, role: 'viewer' })
  await manager.run('recall.expand', { recallId: r.id, version: r.version }, { error: 'FORBIDDEN' })
})


test('TRACE-005 quality-role deviations: exact proposals, independent approval and gated atomic execution release only held units under deviation, with trace, shipment pack, restart and archive restore', async t => {
  const h = await installation(); t.after(() => h.close())
  const manager = await h.person('deviation-manager@example.test', 'manager')
  const opener = await h.person('deviation-opener@example.test', 'quality'), inspector = await h.person('deviation-inspector@example.test', 'quality')
  const quality = await h.person('deviation-approver@example.test', 'quality'), revoked = await h.person('deviation-revoked@example.test', 'quality'), departed = await h.person('deviation-departed@example.test', 'quality')
  const agent = await h.person('deviation-agent@example.test', 'agent'), viewer = await h.person('deviation-viewer@example.test', 'viewer')
  const day = n => new Date(Date.now() + n * 86400000).toISOString().slice(0, 10)
  const location = await h.command('location.save', { name: 'Deviation shelf' })
  const item = await h.command('item.save', { sku: 'DEV-PLATE', name: 'Deviation plate', kind: 'buy', baseUnit: 'each' })
  const supplier = await h.command('party.save', { name: 'Deviation supplier', kind: 'supplier' }), customer = await h.command('party.save', { name: 'Deviation customer', kind: 'customer' })
  let po = await h.command('po.draft', { supplierId: supplier.id, expectedDate: today, reason: 'Deviation proof', lines: [{ itemId: item.id, quantity: '14', unitPrice: '2' }] })
  po = await h.command('po.approve', { poId: po.id, version: po.version })
  const line = (lot, quantity, dates) => ({ lineId: po.lines[0].id, locationId: location.id, quantity, lot, dates })
  await h.command('receipt.create', { poId: po.id, supplierReference: 'DEV-RECEIPT', lines: [line('DEV-LOT', '10'), line('DEV-RECALL', '2'), line('DEV-EXPIRED', '2', { expiresOn: day(-1) })] })
  const lots = (await h.state()).lots, lotId = lots.find(l => l.code === 'DEV-LOT').id
  let order = await h.command('so.quote', { customerId: customer.id, promiseDate: today, lines: [{ itemId: item.id, quantity: '12', unitPrice: '5' }] })
  order = await h.command('so.confirm', { orderId: order.id, version: order.version })
  await h.command('so.reserve', { orderId: order.id })
  let plan = await h.command('quality.plan.save', { itemId: item.id, stage: 'receipt', name: 'Deviation finish', sampleSize: 1, measurements: [{ name: 'Roughness', unit: 'um', target: '1', lower: '0', upper: '2' }] })
  plan = await h.command('quality.plan.approve', { planId: plan.id, version: plan.version })
  // A quality opener contains four units; a different quality inspector records the failure.
  const open = async (code, quantity, by = { opener: opener.run, inspector: inspector.run }) => {
    const n = await by.opener('nonconformance.open', { lotId: lots.find(l => l.code === code).id, locationId: location.id, quantity, complaint: `Finish outside specification on ${code}`, dueOn: today, evidence: [evidence('Complaint')] })
    const failed = await by.inspector('quality.inspect', { planId: plan.id, planVersion: plan.version, nonconformanceId: n.id, quantity, samples: { Roughness: ['3'] }, evidence: [evidence('Failing measurement')] })
    return { n: (await h.state()).nonconformances.find(x => x.id === n.id), failed }
  }
  let { n, failed } = await open('DEV-LOT', '4')
  assert.equal(n.unreserved.length, 1)
  const stock = async () => { const s = await h.invariant(); return { movements: s.movements, positions: s.positions, reservations: s.reservations, inspections: s.inspections, workOrders: s.workOrders } }
  const refused = async (who, type, payload, error) => {
    const before = await stock(), cases = (await h.state()).nonconformances
    await who(type, payload, { error })
    assert.deepEqual(await stock(), before); assert.deepEqual((await h.state()).nonconformances, cases)
  }
  const input = { caseId: n.id, version: n.version, quantity: '1.250000', reason: 'Fit for intended use after engineering review', evidence: [evidence('Engineering assessment')] }
  for (const [who, payload, error] of [[agent.run, input, 'FORBIDDEN'], [viewer.run, input, 'FORBIDDEN'], [manager.run, { ...input, version: n.version - 1 }, 'STALE'], [manager.run, { ...input, quantity: '4.000001' }, 'QUANTITY'], [manager.run, { ...input, quantity: '0' }, 'DECIMAL'], [manager.run, { ...input, reason: '' }, 'INPUT'], [manager.run, { ...input, evidence: [] }, 'INPUT']])
    await refused(who, 'nonconformance.deviation.propose', payload, error)
  const reviewedVersion = n.version
  n = await manager.run('nonconformance.deviation.propose', { ...input, approvedBy: manager.id, status: 'approved' })
  let a = n.deviationProposals[0]
  assert.equal(a.quantity, '1.25'); assert.equal(a.heldAtProposal, '4'); assert.equal(a.caseVersion, reviewedVersion); assert.equal(a.lotId, lotId); assert.equal(a.locationId, location.id)
  assert.equal(a.proposedBy, manager.id); assert.equal(a.status, 'proposed; not approved or released'); assert.equal(a.approvedBy, undefined)
  assert.deepEqual(a.inspections, [{ id: failed.id, version: failed.version, planId: plan.id, planVersion: plan.version, inspectedBy: inspector.id }])
  const file = a.evidence[0], contents = await (await h.request(`/api/larder/attachments/${file.id}`)).arrayBuffer()
  assert.equal(Buffer.from(await crypto.subtle.digest('SHA-256', contents)).toString('hex'), file.sha256)
  n = await manager.run('nonconformance.deviation.propose', { ...input, version: n.version, quantity: '0.5' })
  const c = n.deviationProposals[1]
  n = await h.command('nonconformance.deviation.propose', { ...input, version: n.version, quantity: '1' })
  const b = n.deviationProposals[2]
  // Approval: only an independent live quality-role holder or the owner, never an agent, the proposer, the opener or the latest failing inspector.
  const approve = (d, more = {}) => ({ caseId: n.id, version: n.version, deviationId: d.id, note: 'Use as is; dimensions unaffected', ...more })
  for (const [who, payload, error] of [[agent.run, approve(a), 'FORBIDDEN'], [viewer.run, approve(a), 'FORBIDDEN'], [manager.run, approve(a), 'FORBIDDEN'], [opener.run, approve(a), 'FORBIDDEN'], [inspector.run, approve(a), 'FORBIDDEN'], [h.command, approve(b), 'FORBIDDEN'], [quality.run, approve(a, { version: n.version - 1 }), 'STALE'], [quality.run, approve(a, { note: '' }), 'INPUT'], [quality.run, approve(a, { deviationId: 'missing' }), 'NOT_FOUND']])
    await refused(who, 'nonconformance.deviation.approve', payload, error)
  await refused(quality.run, 'nonconformance.deviation.execute', approve(a), 'STATE')
  const approvalId = crypto.randomUUID()
  n = await quality.run('nonconformance.deviation.approve', approve(a), { commandId: approvalId })
  a = n.deviationProposals[0]
  assert.equal(a.status, 'approved; not yet released'); assert.equal(a.approvedBy, quality.id); assert.equal(a.approverRole, 'quality'); assert.equal(a.version, 2); assert.equal(a.executedAt, undefined)
  assert.deepEqual(await quality.run('nonconformance.deviation.approve', approve(a, { version: n.version - 1 }), { commandId: approvalId }), n)
  await quality.run('nonconformance.deviation.approve', approve(a, { note: 'Changed replay' }), { commandId: approvalId, error: 'IDEMPOTENCY' })
  await h.command('role.set', { operatorId: revoked.id, role: 'production' })
  await refused(revoked.run, 'nonconformance.deviation.approve', approve(c), 'FORBIDDEN')
  const deactivated = await h.request('/auth/operator/status', { method: 'POST', body: { operatorId: departed.id, status: 'inactive' } })
  assert.equal(deactivated.status, 200, await deactivated.text())
  await refused(departed.run, 'nonconformance.deviation.approve', approve(c), 'AUTH')
  n = await quality.run('nonconformance.deviation.approve', approve(c))
  // Execution rechecks recall, expiry/retest and certificate gates and never runs for managers or agents.
  const execute = (d, more = {}) => ({ caseId: n.id, version: n.version, deviationId: d.id, ...more })
  await h.command('certificate.requirements', { itemId: item.id, types: ['coa'], note: 'Customer CoA policy' })
  await refused(h.command, 'nonconformance.deviation.execute', execute(a), 'CERTIFICATE_REQUIRED')
  const policy = (await h.state()).certificatePolicies.find(x => x.itemId === item.id)
  await h.command('certificate.requirements', { itemId: item.id, types: [], version: policy.version, note: 'Policy withdrawn' })
  for (const [who, payload, error] of [[agent.run, execute(a), 'FORBIDDEN'], [manager.run, execute(a), 'FORBIDDEN'], [h.command, execute(a, { version: n.version - 1 }), 'STALE']])
    await refused(who, 'nonconformance.deviation.execute', payload, error)
  const before = await stock(), executeId = crypto.randomUUID()
  n = await h.command('nonconformance.deviation.execute', execute(a), { commandId: executeId })
  assert.deepEqual(await h.command('nonconformance.deviation.execute', execute(a, { version: n.version - 1 }), { commandId: executeId }), n)
  await h.command('nonconformance.deviation.execute', execute(a, { deviationId: c.id }), { commandId: executeId, error: 'IDEMPOTENCY' })
  a = n.deviationProposals[0]
  const label = 'released under deviation; failed results retained, not passed'
  assert.equal(a.status, label); assert.equal(a.executedBy, (await h.state()).actor.id); assert.equal(n.remaining, '2.75')
  assert.deepEqual([a.proposedBy, a.approvedBy], [manager.id, quality.id]); assert.ok(Date.parse(a.proposedAt) <= Date.parse(a.approvedAt) && Date.parse(a.approvedAt) <= Date.parse(a.executedAt))
  assert.deepEqual(n.decisions.map(d => [d.decision, d.reference, d.quantity, d.label, d.approvedBy]), [['deviation', a.reference, '1.25', label, quality.id]])
  const after = await stock(), added = after.movements.slice(before.movements.length)
  assert.deepEqual(added.map(m => [m.kind, m.status, m.quantity, m.lotId, m.documentId]), [['nonconformance-deviation', 'quarantine', '-1.25', lotId, n.id], ['nonconformance-deviation', 'available', '1.25', lotId, n.id]])
  assert.ok(added.every(m => m.reason.startsWith(`Deviation ${a.reference}`)))
  assert.deepEqual(after.positions.filter(p => p.lotId === lotId).map(p => [p.status, p.quantity]).sort(), [['available', '7.25'], ['quarantine', '2.75']])
  assert.deepEqual(after.reservations, before.reservations); assert.deepEqual(after.inspections, before.inspections); assert.deepEqual(after.workOrders, before.workOrders)
  assert.equal(after.inspections.find(i => i.id === failed.id).passed, false)
  // Changed inputs invalidate other approvals and proposals; excess and closed cases are refused.
  await refused(quality.run, 'nonconformance.deviation.execute', execute(c), 'STALE_INPUTS')
  await refused(quality.run, 'nonconformance.deviation.approve', approve(b), 'STALE_INPUTS')
  await refused(manager.run, 'nonconformance.deviation.propose', { ...input, version: n.version, quantity: '2.750001' }, 'QUANTITY')
  // Recalled and expired lots keep their gates.
  const recalled = await open('DEV-RECALL', '1', { opener: h.command, inspector: h.command })
  let r = await manager.run('nonconformance.deviation.propose', { ...input, caseId: recalled.n.id, version: recalled.n.version, quantity: '1' })
  r = await h.command('nonconformance.deviation.approve', { caseId: r.id, version: r.version, deviationId: r.deviationProposals[0].id, note: 'Owner exception: opener and failing inspector' })
  assert.deepEqual([r.createdBy, recalled.failed.inspectedBy, r.deviationProposals[0].approverRole, r.deviationProposals[0].status], [(await h.state()).actor.id, (await h.state()).actor.id, 'owner', 'approved; not yet released'])
  await h.command('recall.open', { lotId: recalled.n.lotId, reason: 'Supplier contamination notice', evidence: [evidence('Supplier notice')] })
  r = (await h.state()).nonconformances.find(x => x.id === r.id)
  await refused(quality.run, 'nonconformance.deviation.execute', { caseId: r.id, version: r.version, deviationId: r.deviationProposals[0].id }, 'RECALL_HOLD')
  const expired = await open('DEV-EXPIRED', '1')
  let e = await manager.run('nonconformance.deviation.propose', { ...input, caseId: expired.n.id, version: expired.n.version, quantity: '1' })
  await refused(quality.run, 'nonconformance.deviation.approve', { caseId: e.id, version: e.version, deviationId: e.deviationProposals[0].id, note: 'Use as is' }, 'LOT_BLOCKED')
  // Trace JSON, CSV and the frozen shipment pack carry the deviation reference.
  const trace = await (await h.request(`/api/larder/lots/${lotId}/trace?direction=downstream`)).json()
  assert.ok(trace.rows.some(x => x.recordType === 'event' && x.kind === 'deviation release' && x.reference === a.reference && x.status === label && x.quantity === '1.25'))
  assert.deepEqual(trace.rows.filter(x => x.recordType === 'movement' && x.kind === 'nonconformance-deviation').map(x => x.reference), [a.reference, a.reference])
  const csv = await (await h.request(`/api/larder/lots/${lotId}/trace.csv?direction=downstream`)).text()
  assert.ok(csv.includes(`"${a.reference}"`) && csv.includes('"deviation release"') && csv.includes(`"${label}"`))
  order = (await h.state()).salesOrders.find(o => o.id === order.id)
  let shipment = await h.command('shipment.pick', { orderId: order.id, lines: [{ lineId: order.lines[0].id, locationId: location.id, quantity: '2', lotId }] })
  shipment = await h.command('shipment.pack', { shipmentId: shipment.id, version: shipment.version, packages: 1 })
  shipment = await h.command('shipment.ship', { shipmentId: shipment.id, version: shipment.version, carrier: 'UPS' })
  const pack = await (await h.request(`/api/larder/shipments/${shipment.id}/certificates.json`)).json()
  assert.deepEqual(pack.trace.flatMap(x => x.deviations ?? []).map(d => [d.reference, d.caseReference, d.quantity, d.approvedBy, d.label]), [[a.reference, n.reference, '1.25', quality.id, label]])
  // The rest is disposed of and the case closes only with an evidenced effective check.
  n = (await h.state()).nonconformances.find(x => x.id === n.id)
  n = await quality.run('nonconformance.reject', { caseId: n.id, version: n.version, quantity: '2.75', reason: 'Remaining units scrapped', evidence: [evidence()] })
  n = await quality.run('nonconformance.update', { caseId: n.id, version: n.version, rootCause: 'Worn tool', correctiveAction: 'Replace tool', nextAction: 'Inspect next batch', dueOn: today, evidence: [evidence()] })
  n = await quality.run('nonconformance.close', { caseId: n.id, version: n.version, effective: true, check: 'Next batch passed', evidence: [evidence('Next batch report')] })
  assert.equal(n.status, 'closed')
  await refused(quality.run, 'nonconformance.deviation.approve', approve(b), 'STATE')
  await h.restart()
  assert.deepEqual((await h.state()).nonconformances.find(x => x.id === n.id), n)
  const archive = await (await h.request('/api/larder/archive')).json()
  const target = await installation(); t.after(() => target.close())
  const restored = await target.request('/api/larder/archive/restore', { method: 'POST', body: archive })
  assert.equal(restored.status, 200, await restored.text())
  assert.deepEqual((await target.invariant()).nonconformances.find(x => x.id === n.id), n)
  assert.ok((await (await target.request(`/api/larder/lots/${lotId}/trace`)).json()).rows.some(x => x.kind === 'deviation release' && x.reference === a.reference))
  assert.deepEqual((await (await target.request(`/api/larder/shipments/${shipment.id}/certificates.json`)).json()).trace.flatMap(x => x.deviations ?? []).map(d => d.reference), [a.reference])
  assert.equal(await (await target.request(`/api/larder/attachments/${file.id}`)).text(), 'Engineering assessment')
})
